 d=pd.read_parquet(OUT/"pit_feature_outcome_table.parquet").copy(); d.trade_date=pd.to_datetime(d.trade_date).dt.normalize(); d.date=pd.to_datetime(d.date).dt.normalize(); d=d[(d.ticker=="NVDA")&~d.executable_pcs&d.trade_date.between("2020-01-02","2023-12-31")].copy(); d["year"]=d.trade_date.dt.year; d["month"]=d.trade_date.dt.to_period("M").astype(str); year=d.groupby("year").agg(rows=("trade_date","size"),standardized_pass=("standardized_pcs_constructable","sum"),option_chain=("option_chain_available","sum"),valid_dte=("valid_dte_available","sum")).reset_index(); month=d.groupby("month").agg(rows=("trade_date","size"),standardized_pass=("standardized_pcs_constructable","sum"),option_chain=("option_chain_available","sum"),valid_dte=("valid_dte_available","sum")).reset_index(); year.to_csv(OUT/"v2_round63_nonexec_blocker_year.csv",index=False); month.to_csv(OUT/"v2_round63_nonexec_blocker_month.csv",index=False); out={"module":"pcs.research.nvda_nonexec_blocker_localization_round63","version":"1.0","symbol":"NVDA","status":"DATA_READINESS_DIAGNOSTIC_ONLY","data_source":"PCS_CANONICAL_DATA","research_mode":"NEW_ENTRY","input_rows":int(len(d)),"pit_feature_date_equals_trade_date":bool((d.date==d.trade_date).all()),"year_rows":year.to_dict(orient="records"),"month_rows":month.to_dict(orient="records"),"universal_standardized_failure":bool((d.standardized_pcs_constructable==False).all()),"repair_performed":False,"validation_read":False,"final_oos_read":False,"production_changes":False,"decision":"UNIVERSAL_NVDA_STANDARDIZED_PCS_READINESS_BLOCKER","reason_codes":["NVDA_ONLY","FULL_PIT_CALENDAR","BLOCKER_LOCALIZED_BY_TIME","NO_DATA_REPAIR","NO_VALIDATION","NO_FINAL_OOS","NO_PRODUCTION_CHANGE"]}; (OUT/"v2_round63_manifest.json").write_text(json.dumps(out,indent=2,default=str),encoding="utf-8"); return out
